local CheeseGraterMaker = {}
local PRODUCTS = {
    iron_cheese_grater = { name = "Železni ribnik za sir", ironCost = 3, woodCost = 1, leatherCost = 1, time = 5, cost = 175, prestige = 3, happiness = 2, description = "Železni ribnik za sir v kuhinji." },
    bronze_cheese_grater = { name = "Bronast ribnik za sir", bronzeCost = 3, ironCost = 1, woodCost = 1, leatherCost = 1, time = 7, cost = 425, prestige = 5, happiness = 3, description = "Bronast ribnik za sir v pekarni." },
    silver_cheese_grater = { name = "Srebrni ribnik za sir", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 1, leatherCost = 1, time = 11, cost = 1025, prestige = 10, happiness = 4, description = "Srebrni ribnik za plemiške kuharje." },
    gilded_cheese_grater = { name = "Pozlačeni ribnik za sir", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 1, leatherCost = 1, time = 15, cost = 2200, prestige = 19, happiness = 5, description = "Pozlačeni ribnik za dvorne kuharje." },
    jewel_set_cheese_grater = { name = "Draguljasti ribnik za sir", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 1, leatherCost = 1, time = 19, cost = 4750, prestige = 35, happiness = 7, description = "Draguljasti ribnik za kraljeve kuharje." },
    royal_sovereign_cheese_grater = { name = "Kraljevski suvereni ribnik za sir", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 26, cost = 10200, prestige = 68, happiness = 13, description = "Suvereni ribnik z biseri za krono." },
}
local BUILDINGS = {
    cheesegrater_workshop = { name = "Ribniška delavnica", cost = { gold = 350, wood = 175, stone = 140, iron = 9 }, upkeep = 6, qualityBonus = 5 },
    cheesegrater_house = { name = "Ribniška hiša", cost = { gold = 1240, wood = 355, stone = 275, silver = 7, iron = 8 }, upkeep = 26, qualityBonus = 18 },
    master_cheesegrater_atelier = { name = "Mojstrski ribniški atelje", cost = { gold = 3100, wood = 415, stone = 530, silver = 37, gold = 7 }, upkeep = 73, qualityBonus = 30 },
    sovereign_cheesegrater_palace = { name = "Suverena ribniška palača", cost = { gold = 13200, wood = 635, stone = 840, gold = 85, jewel = 19 }, upkeep = 258, qualityBonus = 55, prestigeBonus = 50 },
}
CheeseGraterMaker.ironStock = 14; CheeseGraterMaker.bronzeStock = 12; CheeseGraterMaker.woodStock = 10; CheeseGraterMaker.leatherStock = 8; CheeseGraterMaker.silverStock = 8; CheeseGraterMaker.goldStock = 6; CheeseGraterMaker.jewelStock = 4; CheeseGraterMaker.pearlStock = 4
CheeseGraterMaker.productStock = {}; CheeseGraterMaker.buildings = {}; CheeseGraterMaker.maker = nil; CheeseGraterMaker.activeMaking = {}; CheeseGraterMaker.totalProducts = 0; CheeseGraterMaker.dayTimer = 0
function CheeseGraterMaker.init() CheeseGraterMaker.ironStock=14; CheeseGraterMaker.bronzeStock=12; CheeseGraterMaker.woodStock=10; CheeseGraterMaker.leatherStock=8; CheeseGraterMaker.silverStock=8; CheeseGraterMaker.goldStock=6; CheeseGraterMaker.jewelStock=4; CheeseGraterMaker.pearlStock=4; CheeseGraterMaker.productStock={}; CheeseGraterMaker.buildings={}; CheeseGraterMaker.maker=nil; CheeseGraterMaker.activeMaking={}; CheeseGraterMaker.totalProducts=0; CheeseGraterMaker.dayTimer=0; print("[CheeseGraterMaker] Royal Cheese Grater Maker System initialized (6 products, 4 buildings)") end
function CheeseGraterMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CheeseGraterMaker.maker={name=n or ("Ribnikar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ribnikar najet: %s (spretnost: %d)",CheeseGraterMaker.maker.name,s),"success") end; return true end
function CheeseGraterMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CheeseGraterMaker.build(id) local ok,e=CheeseGraterMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CheeseGraterMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CheeseGraterMaker.getQualityBonus() local b=0; for _,bd in ipairs(CheeseGraterMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CheeseGraterMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and CheeseGraterMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and CheeseGraterMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and CheeseGraterMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and CheeseGraterMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and CheeseGraterMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CheeseGraterMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CheeseGraterMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CheeseGraterMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CheeseGraterMaker.buildings==0 then return false,"Potrebna ribniška delavnica" end; if not CheeseGraterMaker.maker then return false,"Potreben ribnikar" end; return true end
function CheeseGraterMaker.make(pt,qty) qty=qty or 1; local ok,e=CheeseGraterMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then CheeseGraterMaker.ironStock=CheeseGraterMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then CheeseGraterMaker.bronzeStock=CheeseGraterMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then CheeseGraterMaker.woodStock=CheeseGraterMaker.woodStock-d.woodCost*qty end; if d.leatherCost then CheeseGraterMaker.leatherStock=CheeseGraterMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then CheeseGraterMaker.silverStock=CheeseGraterMaker.silverStock-d.silverCost*qty end; if d.goldCost then CheeseGraterMaker.goldStock=CheeseGraterMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CheeseGraterMaker.jewelStock=CheeseGraterMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then CheeseGraterMaker.pearlStock=CheeseGraterMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if CheeseGraterMaker.maker then t=math.max(1,t-math.floor(CheeseGraterMaker.maker.skill/13)) end; table.insert(CheeseGraterMaker.activeMaking,{id="cheesegrater_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CheeseGraterMaker.completeMaking(m) local q=1.0+(CheeseGraterMaker.getQualityBonus()/100); if CheeseGraterMaker.maker then q=q+(CheeseGraterMaker.maker.skill/140) end; q=math.min(2.5,q); CheeseGraterMaker.productStock[m.productType]=(CheeseGraterMaker.productStock[m.productType] or 0)+m.quantity; CheeseGraterMaker.totalProducts=CheeseGraterMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CheeseGraterMaker.maker then CheeseGraterMaker.maker.itemsMade=CheeseGraterMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then CheeseGraterMaker.maker.skill=math.min(100,CheeseGraterMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ribnik izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"cheesegrater.completed",{productName=m.productName,prestige=m.prestige,happiness:m.happiness}) end end
function CheeseGraterMaker.update(dt) if not _G.state then return end; CheeseGraterMaker.dayTimer=CheeseGraterMaker.dayTimer+dt; if CheeseGraterMaker.dayTimer>=30 then CheeseGraterMaker.dayTimer=0; for i=#CheeseGraterMaker.activeMaking,1,-1 do local m=CheeseGraterMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CheeseGraterMaker.completeMaking(m); table.remove(CheeseGraterMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CheeseGraterMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CheeseGraterMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CheeseGraterMaker.getStats() return {ironStock=CheeseGraterMaker.ironStock,bronzeStock=CheeseGraterMaker.bronzeStock,woodStock=CheeseGraterMaker.woodStock,leatherStock=CheeseGraterMaker.leatherStock,silverStock=CheeseGraterMaker.silverStock,goldStock=CheeseGraterMaker.goldStock,jewelStock=CheeseGraterMaker.jewelStock,pearlStock=CheeseGraterMaker.pearlStock,productStock=CheeseGraterMaker.productStock,numBuildings=#CheeseGraterMaker.buildings,hasMaker=CheeseGraterMaker.maker~=nil,makerName=CheeseGraterMaker.maker and CheeseGraterMaker.maker.name or "—",makerSkill=CheeseGraterMaker.maker and CheeseGraterMaker.maker.skill or 0,activeMaking=#CheeseGraterMaker.activeMaking,totalProducts=CheeseGraterMaker.totalProducts} end
return CheeseGraterMaker
